  "privFooter": "Privasi & storan",
  "privTitle": "Privasi dan storan pelayar",
  "privClose": "Tutup notis privasi",
  "privWho": "Siapa yang bertanggungjawab?",
  "privWhat": "Apa yang kami gunakan dan mengapa",
  "privStorage": "Storan pelayar",
  "privOther": "Ciri sedia ada yang lain",
  "privProviders": "Pembekal perkhidmatan dan pemindahan antarabangsa",
  "privRetention": "Penyimpanan dan pemadaman",
  "privRights": "Hak anda",
  "noticeReopen": "Notis storan",
  "noticeLabel": "Notis storan pelayar",
  "noticeText": "Cook menggunakan storan pelayar untuk ciri memasak dan log masuk yang anda gunakan. Tiada storan untuk iklan atau analitik ditambah.",
  "noticeClose": "Tutup notis storan",
  "privDraftLabel": "Draf — dikemas kini pada 28 Oktober 2026.",
  "privDraft": "Ciri akaun sedang diuji. Butiran pengendali dan perkhidmatan di bawah mesti dilengkapkan sebelum pelancaran awam.",
  "privWho1": "Cook dikendalikan oleh [nama sah dan alamat pos pengendali]. Hubungi [alamat e-mel privasi] untuk soalan dan permintaan privasi. Butiran ini mesti dilengkapkan sebelum pendaftaran dibuka.",
  "privWhat1": "Apabila anda mencipta akaun, kami menggunakan e-mel anda, pengecam akaun, rekod pengesahan kata laluan dan status pengesahan untuk menyediakan dan melindungi akaun anda. Kata laluan dikendalikan oleh pembekal pengesahan sebagai cincangan selamat; Cook tidak menyimpan kata laluan yang boleh dibaca. Kami menyimpan susun atur dapur, bahasa yang dipilih, tema dan unit ukuran untuk memulihkan tetapan anda pada semua peranti. E-mel dan kata laluan diperlukan untuk akaun; anda boleh melihat resipi tanpa akaun.",
  "privWhat2": "Pemprosesan akaun dan tetapan diperlukan untuk menyediakan perkhidmatan akaun yang anda minta (GDPR Perkara 6(1)(b)). Rekod terhad untuk keselamatan dan pencegahan penyalahgunaan boleh diproses atas dasar kepentingan sah (Perkara 6(1)(f)), setakat yang perlu dan selepas penimbangan. E-mel pengesahan dan set semula kata laluan ialah mesej perkhidmatan, bukan pemasaran. Ciri akaun tidak menambah iklan atau analitik.",
  "privStorage1": "Cook menggunakan sessionStorage untuk membawa dapur, kemajuan memasak dan pilihan anda antara halaman dalam tab yang sama. Apabila anda log masuk, ia juga menyimpan sesi pengesahan anda. Pelayar biasanya mengosongkannya apabila sesi tab tamat, tetapi pemulihan sesi pelayar boleh mengekalkannya. Log keluar mengosongkan data tab Cook. Penutupan notis storan hanya diingati dalam tab itu. Skrip Cook sendiri tidak menetapkan kuki. Pembekal pengehosan atau perkhidmatan anda mungkin mempunyai pemprosesan keselamatan sendiri yang mesti didokumenkan sebelum pelancaran.",
  "privStorage2": "OK dan butang tutup pada notis storan hanya menutup notis. Ia tidak membenarkan analitik, iklan atau penjejakan pilihan lain. Sebarang storan tidak penting pada masa hadapan memerlukan pilihan berasingan sebelum bermula, dengan penolakan dan penarikan balik yang sama mudah.",
  "privOther1": "Ciri suara senarai resipi semasa meminta negara anggaran daripada country.is menggunakan alamat IP anda untuk memilih bahasa pengecaman pertuturan. Jika anda menggunakan pengecaman mikrofon, pelayar anda mungkin menghantar audio kepada pembekal perkhidmatan pengecaman pertuturannya. Anda juga boleh menaip bahan. Pembekal ini, dasar mereka dan asas undang-undang ciri ini mesti disemak sebelum pelancaran awam.",
  "privProviders1": "Pembekal akaun yang dirancang: Supabase (PostgreSQL dan pengesahan terurus), dengan rantau pangkalan data terpilih di EU. Pembekal e-mel: [pembekal]. Pengehos laman web: [pembekal]. Pengendali mesti mengesahkan pembekal sebenar, perjanjian pemprosesan, subpemproses, lokasi log dan sebarang pemindahan ke luar EEA. Rantau pangkalan data di EU tidak dengan sendirinya mengecualikan pemindahan antarabangsa. Jika berkaitan, nyatakan keputusan kecukupan atau perlindungan kontrak yang terpakai dan cara mendapatkan salinannya.",
  "privRetention1": "Tetapan akaun disimpan selagi akaun anda aktif. Anda boleh meminta pemadaman melalui hubungan privasi di atas. Sebelum pelancaran, pengendali mesti menetapkan proses respons permintaan pemadaman, tempoh luput akaun yang belum disahkan, serta tempoh penyimpanan log keselamatan dan sandaran. Data yang dipadam mungkin kekal dalam sandaran dengan akses terhad sehingga tempoh penyimpanan sandaran yang didokumenkan tamat.",
  "privRights1": "Bergantung pada syarat yang terpakai, anda boleh meminta akses, pembetulan, pemadaman, sekatan atau kemudahalihan, atau membantah pemprosesan atas dasar kepentingan sah. Hubungi pengendali di atas; permintaan biasanya dijawab dalam tempoh sebulan, dan sebarang lanjutan yang sah akan dijelaskan. Anda boleh membuat aduan kepada pihak berkuasa penyeliaan, termasuk NAIH Hungary di naih.hu. Cook tidak menggunakan tetapan akaun untuk keputusan automatik yang mempunyai kesan undang-undang atau kesan ketara yang serupa.",
  "favOnly": "Kegemaran sahaja",
